                sb.append("CJUMP ").append(e1.code).append(" ").append(lf).append("\n");
                sb.append("CJUMP ").append(e2.code).append(" ").append(lf).append("\n");
                sb.append("MOVE TEMP ").append(res).append(" 1\n");
                sb.append(lf).append(" NOOP\n");
